16	For sample $y_i$ with tokens $t_1, \ldots, t_{|y_i|}$:
17	\begin{equation}\label{eq:logprob}
18	c_{\text{lp}}(y_i) = \frac{1}{|y_i|} \sum_{j=1}^{|y_i|} \log p_{\mathcal{M}}(t_j \mid t_{<j}, x)
19	\end{equation}
